'use client';

import { Button } from '@/components/ui/button';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';
import { cjk } from '@streamdown/cjk';
import { code } from '@streamdown/code';
import { math } from '@streamdown/math';
import { mermaid } from '@streamdown/mermaid';
import type { UIMessage } from 'ai';
import type { ComponentProps, HTMLAttributes } from 'react';
import { memo } from 'react';
import { Streamdown } from 'streamdown';

export * from './message-branch';

export type MessageProps = HTMLAttributes<HTMLDivElement> & {
  from: UIMessage['role'];
};

export const Message = ({ className, from, ...props }: MessageProps) => (
  <div
    className={cn(
      'group flex w-full max-w-[95%] flex-col gap-2',
      from === 'user' ? 'is-user ml-auto justify-end' : 'is-assistant',
      className
    )}
    {...props}
  />
);

export type MessageContentProps = HTMLAttributes<HTMLDivElement>;

export const MessageContent = ({ children, className, ...props }: MessageContentProps) => (
  <div
    className={cn(
      'is-user:dark flex w-fit max-w-full min-w-0 flex-col gap-2 overflow-hidden text-sm',
      'group-[.is-user]:ml-auto group-[.is-user]:rounded-lg group-[.is-user]:bg-secondary group-[.is-user]:px-4 group-[.is-user]:py-3 group-[.is-user]:text-foreground',
      'group-[.is-assistant]:text-foreground',
      className
    )}
    {...props}
  >
    {children}
  </div>
);

export type MessageActionsProps = ComponentProps<'div'>;

export const MessageActions = ({ className, children, ...props }: MessageActionsProps) => (
  <div className={cn('flex items-center gap-1', className)} {...props}>
    {children}
  </div>
);

export type MessageActionProps = ComponentProps<typeof Button> & {
  tooltip?: string;
  label?: string;
};

export const MessageAction = ({
  tooltip,
  children,
  label,
  variant = 'ghost',
  size = 'icon-sm',
  ...props
}: MessageActionProps) => {
  const button = (
    <Button size={size} type="button" variant={variant} {...props}>
      {children}
      <span className="sr-only">{label || tooltip}</span>
    </Button>
  );

  if (tooltip) {
    return (
      <TooltipProvider>
        <Tooltip>
          <TooltipTrigger asChild>{button}</TooltipTrigger>
          <TooltipContent>
            <p>{tooltip}</p>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  }

  return button;
};

export type MessageResponseProps = ComponentProps<typeof Streamdown>;

const streamdownPlugins = { cjk, code, math, mermaid };

export const MessageResponse = memo(
  ({ className, ...props }: MessageResponseProps) => (
    <Streamdown
      className={cn('size-full [&>*:first-child]:mt-0 [&>*:last-child]:mb-0', className)}
      plugins={streamdownPlugins}
      {...props}
    />
  ),
  (prevProps, nextProps) =>
    prevProps.children === nextProps.children && nextProps.isAnimating === prevProps.isAnimating
);

MessageResponse.displayName = 'MessageResponse';

export type MessageToolbarProps = ComponentProps<'div'>;

export const MessageToolbar = ({ className, children, ...props }: MessageToolbarProps) => (
  <div className={cn('mt-4 flex w-full items-center justify-between gap-4', className)} {...props}>
    {children}
  </div>
);

'use client';

import { useControllableState } from '@radix-ui/react-use-controllable-state';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';
import { cn } from '@/lib/utils';
import { cjk } from '@streamdown/cjk';
import { code } from '@streamdown/code';
import { math } from '@streamdown/math';
import { mermaid } from '@streamdown/mermaid';
import { BrainIcon, ChevronDownIcon } from 'lucide-react';
import type { ComponentProps, ReactNode } from 'react';
import {
  createContext,
  memo,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { Streamdown } from 'streamdown';

import { Shimmer } from './shimmer';

interface ReasoningContextValue {
  isStreaming: boolean;
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  duration: number | undefined;
}

const ReasoningContext = createContext<ReasoningContextValue | null>(null);

export const useReasoning = () => {
  const context = useContext(ReasoningContext);
  if (!context) {
    throw new Error('Reasoning components must be used within Reasoning');
  }
  return context;
};

export type ReasoningProps = ComponentProps<typeof Collapsible> & {
  isStreaming?: boolean;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  duration?: number;
};

const AUTO_CLOSE_DELAY = 1000;
const MS_IN_S = 1000;

export const Reasoning = memo(
  ({
    className,
    isStreaming = false,
    open,
    defaultOpen,
    onOpenChange,
    duration: durationProp,
    children,
    ...props
  }: ReasoningProps) => {
    const resolvedDefaultOpen = defaultOpen ?? isStreaming;
    // Track if defaultOpen was explicitly set to false (to prevent auto-open)
    const isExplicitlyClosed = defaultOpen === false;

    const [isOpen, setIsOpen] = useControllableState<boolean>({
      defaultProp: resolvedDefaultOpen,
      onChange: onOpenChange,
      prop: open,
    });
    const [duration, setDuration] = useControllableState<number | undefined>({
      defaultProp: undefined,
      prop: durationProp,
    });

    const hasEverStreamedRef = useRef(isStreaming);
    const [hasAutoClosed, setHasAutoClosed] = useState(false);
    const startTimeRef = useRef<number | null>(null);

    // Track when streaming starts and compute duration
    useEffect(() => {
      if (isStreaming) {
        hasEverStreamedRef.current = true;
        if (startTimeRef.current === null) {
          startTimeRef.current = Date.now();
        }
      } else if (startTimeRef.current !== null) {
        setDuration(Math.ceil((Date.now() - startTimeRef.current) / MS_IN_S));
        startTimeRef.current = null;
      }
    }, [isStreaming, setDuration]);

    // Auto-open when streaming starts (unless explicitly closed)
    useEffect(() => {
      if (isStreaming && !isOpen && !isExplicitlyClosed) {
        setIsOpen(true);
      }
    }, [isStreaming, isOpen, setIsOpen, isExplicitlyClosed]);

    // Auto-close when streaming ends (once only, and only if it ever streamed)
    useEffect(() => {
      if (hasEverStreamedRef.current && !isStreaming && isOpen && !hasAutoClosed) {
        const timer = setTimeout(() => {
          setIsOpen(false);
          setHasAutoClosed(true);
        }, AUTO_CLOSE_DELAY);

        return () => clearTimeout(timer);
      }
    }, [isStreaming, isOpen, setIsOpen, hasAutoClosed]);

    const handleOpenChange = useCallback(
      (newOpen: boolean) => {
        setIsOpen(newOpen);
      },
      [setIsOpen]
    );

    const contextValue = useMemo(
      () => ({ duration, isOpen, isStreaming, setIsOpen }),
      [duration, isOpen, isStreaming, setIsOpen]
    );

    return (
      <ReasoningContext.Provider value={contextValue}>
        <Collapsible
          className={cn('not-prose mb-4', className)}
          onOpenChange={handleOpenChange}
          open={isOpen}
          {...props}
        >
          {children}
        </Collapsible>
      </ReasoningContext.Provider>
    );
  }
);

export type ReasoningTriggerProps = ComponentProps<typeof CollapsibleTrigger> & {
  getThinkingMessage?: (isStreaming: boolean, duration?: number) => ReactNode;
};

const defaultGetThinkingMessage = (isStreaming: boolean, duration?: number) => {
  if (isStreaming || duration === 0) {
    return <Shimmer duration={1}>Thinking...</Shimmer>;
  }
  if (duration === undefined) {
    return <p>Thought for a few seconds</p>;
  }
  return <p>Thought for {duration} seconds</p>;
};

export const ReasoningTrigger = memo(
  ({
    className,
    children,
    getThinkingMessage = defaultGetThinkingMessage,
    ...props
  }: ReasoningTriggerProps) => {
    const { isStreaming, isOpen, duration } = useReasoning();

    return (
      <CollapsibleTrigger
        className={cn(
          'flex w-full items-center gap-2 text-sm text-muted-foreground transition-colors hover:text-foreground',
          className
        )}
        {...props}
      >
        {children ?? (
          <>
            <BrainIcon className="size-4" />
            {getThinkingMessage(isStreaming, duration)}
            <ChevronDownIcon
              className={cn('size-4 transition-transform', isOpen ? 'rotate-180' : 'rotate-0')}
            />
          </>
        )}
      </CollapsibleTrigger>
    );
  }
);

export type ReasoningContentProps = ComponentProps<typeof CollapsibleContent> & {
  children: string;
};

const streamdownPlugins = { cjk, code, math, mermaid };

export const ReasoningContent = memo(({ className, children, ...props }: ReasoningContentProps) => (
  <CollapsibleContent
    className={cn(
      'mt-4 text-sm',
      'data-[state=closed]:fade-out-0 data-[state=closed]:slide-out-to-top-2 data-[state=open]:slide-in-from-top-2 data-[state=closed]:animate-out data-[state=open]:animate-in text-muted-foreground outline-none',
      className
    )}
    {...props}
  >
    <Streamdown plugins={streamdownPlugins}>{children}</Streamdown>
  </CollapsibleContent>
));

Reasoning.displayName = 'Reasoning';
ReasoningTrigger.displayName = 'ReasoningTrigger';
ReasoningContent.displayName = 'ReasoningContent';

'use client';

import { Badge } from '@/components/ui/badge';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';
import { cn } from '@/lib/utils';
import type { DynamicToolUIPart, ToolUIPart } from 'ai';
import {
  CheckCircleIcon,
  ChevronDownIcon,
  CircleIcon,
  ClockIcon,
  WrenchIcon,
  XCircleIcon,
} from 'lucide-react';
import type { ComponentProps, ReactNode } from 'react';
import { isValidElement } from 'react';

import { CodeBlock } from './code-block';

export type ToolProps = ComponentProps<typeof Collapsible>;

export const Tool = ({ className, ...props }: ToolProps) => (
  <Collapsible
    className={cn('group not-prose mb-4 w-full rounded-md border', className)}
    {...props}
  />
);

export type ToolPart = ToolUIPart | DynamicToolUIPart;

export type ToolHeaderProps = {
  title?: string;
  className?: string;
} & (
  | { type: ToolUIPart['type']; state: ToolUIPart['state']; toolName?: never }
  | {
      type: DynamicToolUIPart['type'];
      state: DynamicToolUIPart['state'];
      toolName: string;
    }
);

const statusLabels: Record<ToolPart['state'], string> = {
  'approval-requested': 'Awaiting Approval',
  'approval-responded': 'Responded',
  'input-available': 'Running',
  'input-streaming': 'Pending',
  'output-available': 'Completed',
  'output-denied': 'Denied',
  'output-error': 'Error',
};

const statusIcons: Record<ToolPart['state'], ReactNode> = {
  'approval-requested': <ClockIcon className="size-4 text-yellow-600" />,
  'approval-responded': <CheckCircleIcon className="size-4 text-blue-600" />,
  'input-available': <ClockIcon className="size-4 animate-pulse" />,
  'input-streaming': <CircleIcon className="size-4" />,
  'output-available': <CheckCircleIcon className="size-4 text-green-600" />,
  'output-denied': <XCircleIcon className="size-4 text-orange-600" />,
  'output-error': <XCircleIcon className="size-4 text-red-600" />,
};

export const getStatusBadge = (status: ToolPart['state']) => (
  <Badge className="gap-1.5 rounded-full text-xs" variant="secondary">
    {statusIcons[status]}
    {statusLabels[status]}
  </Badge>
);

export const ToolHeader = ({
  className,
  title,
  type,
  state,
  toolName,
  ...props
}: ToolHeaderProps) => {
  const derivedName = type === 'dynamic-tool' ? toolName : type.split('-').slice(1).join('-');

  return (
    <CollapsibleTrigger
      className={cn('flex w-full items-center justify-between gap-4 p-3', className)}
      {...props}
    >
      <div className="flex items-center gap-2">
        <WrenchIcon className="size-4 text-muted-foreground" />
        <span className="text-sm font-medium">{title ?? derivedName}</span>
        {getStatusBadge(state)}
      </div>
      <ChevronDownIcon className="size-4 text-muted-foreground transition-transform group-data-[state=open]:rotate-180" />
    </CollapsibleTrigger>
  );
};

export type ToolContentProps = ComponentProps<typeof CollapsibleContent>;

export const ToolContent = ({ className, ...props }: ToolContentProps) => (
  <CollapsibleContent
    className={cn(
      'data-[state=closed]:fade-out-0 data-[state=closed]:slide-out-to-top-2 data-[state=open]:slide-in-from-top-2 data-[state=closed]:animate-out data-[state=open]:animate-in space-y-4 p-4 text-popover-foreground outline-none',
      className
    )}
    {...props}
  />
);

export type ToolInputProps = ComponentProps<'div'> & {
  input: ToolPart['input'];
};

export const ToolInput = ({ className, input, ...props }: ToolInputProps) => (
  <div className={cn('space-y-2 overflow-hidden', className)} {...props}>
    <h4 className="text-xs font-medium tracking-wide text-muted-foreground uppercase">
      Parameters
    </h4>
    <div className="rounded-md bg-muted/50">
      <CodeBlock code={JSON.stringify(input, null, 2)} language="json" />
    </div>
  </div>
);

export type ToolOutputProps = ComponentProps<'div'> & {
  output: ToolPart['output'];
  errorText: ToolPart['errorText'];
};

export const ToolOutput = ({ className, output, errorText, ...props }: ToolOutputProps) => {
  if (!(output || errorText)) {
    return null;
  }

  let Output = <div>{output as ReactNode}</div>;

  if (typeof output === 'object' && !isValidElement(output)) {
    Output = <CodeBlock code={JSON.stringify(output, null, 2)} language="json" />;
  } else if (typeof output === 'string') {
    Output = <CodeBlock code={output} language="json" />;
  }

  return (
    <div className={cn('space-y-2', className)} {...props}>
      <h4 className="text-xs font-medium tracking-wide text-muted-foreground uppercase">
        {errorText ? 'Error' : 'Result'}
      </h4>
      <div
        className={cn(
          'overflow-x-auto rounded-md text-xs [&_table]:w-full',
          errorText ? 'bg-destructive/10 text-destructive' : 'bg-muted/50 text-foreground'
        )}
      >
        {errorText && <div>{errorText}</div>}
        {Output}
      </div>
    </div>
  );
};

import type { Meta, StoryObj } from '@storybook/nextjs-vite';
import { expect, userEvent, within } from 'storybook/test';

import { Reasoning, ReasoningContent, ReasoningTrigger } from './reasoning';

const TRACE =
  'Working through the request step by step: first parse the intent, then pick the tool, then answer.';

const meta = {
  title: 'AI Elements/Reasoning',
  component: Reasoning,
} satisfies Meta<typeof Reasoning>;

export default meta;

type Story = StoryObj<typeof meta>;

const columnStyle = {
  display: 'flex',
  flexDirection: 'column' as const,
  gap: '1.5rem',
  maxWidth: '32rem',
};

export const Default: Story = {
  render: () => (
    <Reasoning defaultOpen duration={4}>
      <ReasoningTrigger />
      <ReasoningContent>{TRACE}</ReasoningContent>
    </Reasoning>
  ),
};

export const StateMatrix: Story = {
  render: () => (
    <div style={columnStyle}>
      {/* streaming: shimmer trigger, auto-opened */}
      <Reasoning isStreaming>
        <ReasoningTrigger />
        <ReasoningContent>{TRACE}</ReasoningContent>
      </Reasoning>
      {/* settled + expanded */}
      <Reasoning defaultOpen duration={6}>
        <ReasoningTrigger />
        <ReasoningContent>{TRACE}</ReasoningContent>
      </Reasoning>
      {/* settled + collapsed */}
      <Reasoning defaultOpen={false} duration={6}>
        <ReasoningTrigger />
        <ReasoningContent>{TRACE}</ReasoningContent>
      </Reasoning>
    </div>
  ),
};

export const Focus: Story = {
  render: () => (
    <Reasoning defaultOpen duration={4}>
      <ReasoningTrigger />
      <ReasoningContent>{TRACE}</ReasoningContent>
    </Reasoning>
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const trigger = await canvas.findByRole('button');
    trigger.focus();
    await expect(trigger).toHaveFocus();
  },
};

export const Keyboard: Story = {
  render: () => (
    <Reasoning defaultOpen={false} duration={4}>
      <ReasoningTrigger />
      <ReasoningContent>{TRACE}</ReasoningContent>
    </Reasoning>
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const trigger = await canvas.findByRole('button');
    await expect(trigger).toHaveAttribute('aria-expanded', 'false');

    trigger.focus();
    await expect(trigger).toHaveFocus();

    await userEvent.keyboard('{Enter}');
    await expect(trigger).toHaveAttribute('aria-expanded', 'true');

    await userEvent.keyboard('{Enter}');
    await expect(trigger).toHaveAttribute('aria-expanded', 'false');
  },
};

export const ExpandCollapseFlow: Story = {
  render: () => (
    <Reasoning defaultOpen={false} duration={4}>
      <ReasoningTrigger />
      <ReasoningContent>{TRACE}</ReasoningContent>
    </Reasoning>
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const trigger = await canvas.findByRole('button');

    // Closed: content is not mounted.
    await expect(trigger).toHaveAttribute('aria-expanded', 'false');
    expect(canvas.queryByText(/step by step/i)).not.toBeInTheDocument();

    // Expand: content becomes visible.
    await userEvent.click(trigger);
    await expect(trigger).toHaveAttribute('aria-expanded', 'true');
    await expect(await canvas.findByText(/step by step/i)).toBeInTheDocument();

    // Collapse again.
    await userEvent.click(trigger);
    await expect(trigger).toHaveAttribute('aria-expanded', 'false');
  },
};

export const CollapseTransition: Story = {
  parameters: { chromatic: { pauseAnimationAtEnd: true } },
  render: () => (
    <Reasoning defaultOpen duration={4}>
      <ReasoningTrigger />
      <ReasoningContent>{TRACE}</ReasoningContent>
    </Reasoning>
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const trigger = await canvas.findByRole('button');
    await expect(trigger).toHaveAttribute('aria-expanded', 'true');

    await userEvent.click(trigger);
    await expect(trigger).toHaveAttribute('aria-expanded', 'false');
  },
};

export const StreamingStates: Story = {
  // Infinite shimmer while streaming; skip the visual-regression snapshot.
  parameters: { chromatic: { disableSnapshot: true } },
  render: () => (
    <div style={columnStyle}>
      {/* pending / streaming */}
      <Reasoning isStreaming>
        <ReasoningTrigger />
        <ReasoningContent>{TRACE}</ReasoningContent>
      </Reasoning>
      {/* settled */}
      <Reasoning defaultOpen duration={5}>
        <ReasoningTrigger />
        <ReasoningContent>{TRACE}</ReasoningContent>
      </Reasoning>
    </div>
  ),
};

export const Docs: Story = {
  render: () => (
    <Reasoning defaultOpen duration={3}>
      <ReasoningTrigger />
      <ReasoningContent>{TRACE}</ReasoningContent>
    </Reasoning>
  ),
};

{
  "policyVersion": "1",
  "upstream": {
    "primitives": "https://ui.shadcn.com/r/styles/new-york",
    "aiElements": "https://elements.ai-sdk.dev/api/registry"
  },
  "invariants": [
    {
      "id": "focus-ring-policy",
      "directory": "src/components/ui",
      "forbid": ["focus-visible:ring-", "focus:ring-"],
      "reason": "The repo focus ring is a themed neutral applied through the `focus-ring` utility. shadcn ships `focus-visible:ring-1 focus-visible:ring-ring` (and older styles `focus:ring-2`), which re-derives the ring from the accent — and the accent is becoming a user knob, so nothing functional may derive from it.",
      "instead": "focus-visible:focus-ring"
    },
    {
      "id": "destructive-is-not-a-fill",
      "directory": "src/components/ui",
      "forbid": ["bg-destructive(?![-/])"],
      "reason": "`--destructive` is a TEXT colour (`semantic.color.text.error`, tuned to read on a dark ground). Used as a solid fill it puts white on #ff6467 for 2.89:1, below the 4.5:1 minimum. A tonal `bg-destructive/10` is fine; a solid fill is not.",
      "instead": "bg-destructive-surface"
    }
  ],
  "deviations": [
    {
      "id": "badge-destructive-surface",
      "file": "src/components/ui/badge.tsx",
      "require": ["bg-destructive-surface"],
      "reason": "Solid destructive badge must use the dedicated surface role (6.42:1 with white in both themes), not the text colour."
    },
    {
      "id": "badge-status-variants",
      "file": "src/components/ui/badge.tsx",
      "require": ["bg-success/10", "bg-warning/10", "bg-destructive/10"],
      "reason": "Tonal status variants added on top of upstream's four. Without them, organisms hand-paint status chips at the call site over `variant=\"secondary\"`."
    },
    {
      "id": "button-destructive-surface",
      "file": "src/components/ui/button.tsx",
      "require": ["bg-destructive-surface"],
      "reason": "Button carried the same white-on-#ff6467 pair as badge. Same fix, same reason."
    },
    {
      "id": "button-icon-sm-size",
      "file": "src/components/ui/button.tsx",
      "require": ["'icon-sm'"],
      "reason": "Added size not present upstream. ai-elements toolbars need a 32px icon button; without it they set `className=\"h-8 w-8\"` at every call site."
    },
    {
      "id": "button-link-not-accent",
      "file": "src/components/ui/button.tsx",
      "require": ["link: 'text-info"],
      "reason": "Upstream's link variant is `text-primary`, which resolves to the accent (#155dfc) and gives 3.42:1 on the dark ground — below the 4.5:1 minimum for text. The accent is becoming a user knob, so no text colour may derive from it. `info` is a themed role: 6.80:1 dark, 6.83:1 light.",
      "instead": "text-info"
    },
    {
      "id": "hover-card-portal",
      "file": "src/components/ui/hover-card.tsx",
      "require": ["HoverCardPrimitive\\.Portal"],
      "reason": "Inline citations render inside <p>. Upstream's un-portalled content makes h4/p/blockquote descendants of a paragraph, which is invalid HTML and reflows unpredictably."
    },
    {
      "id": "command-no-dialog",
      "file": "src/components/ui/command.tsx",
      "forbid": ["CommandDialog"],
      "reason": "Upstream's CommandDialog pulls in the dialog primitive for a subcomponent nothing here uses, and pushes the file over the LOC guard."
    }
  ],
  "contracts": [
    {
      "id": "agent-tool-type",
      "file": "src/components/ai-elements/agent.tsx",
      "require": ["import type \\{[^}]*\\bTool\\b[^}]*\\} from 'ai'"],
      "reason": "Agent is typed against the AI SDK tool definition."
    },
    {
      "id": "attachments-file-parts",
      "file": "src/components/ai-elements/attachments.tsx",
      "require": ["import type \\{[^}]*\\bFileUIPart\\b[^}]*\\} from 'ai'"],
      "reason": "Attachments consume the SDK's file/source message parts rather than a local shape."
    },
    {
      "id": "confirmation-tool-part",
      "file": "src/components/ai-elements/confirmation.tsx",
      "require": ["import type \\{[^}]*\\bToolUIPart\\b[^}]*\\} from 'ai'"],
      "reason": "Confirmation renders a tool-call part straight off the message stream."
    },
    {
      "id": "context-usage-type",
      "file": "src/components/ai-elements/context.tsx",
      "require": ["import type \\{[^}]*\\bLanguageModelUsage\\b[^}]*\\} from 'ai'"],
      "reason": "The context meter reads the SDK's usage record; a local shape would silently drift from provider field moves."
    },
    {
      "id": "context-usage-tokenlens",
      "file": "src/components/ai-elements/context-usage.tsx",
      "require": ["from 'tokenlens"],
      "reason": "Context window sizes come from tokenlens, not a hand-maintained table."
    },
    {
      "id": "image-generated-type",
      "file": "src/components/ai-elements/image.tsx",
      "require": ["import type \\{[^}]*\\bExperimental_GeneratedImage\\b[^}]*\\} from 'ai'"],
      "reason": "Image renders the SDK's generated-image payload."
    },
    {
      "id": "message-ui-message",
      "file": "src/components/ai-elements/message.tsx",
      "require": ["import type \\{[^}]*\\bUIMessage\\b[^}]*\\} from 'ai'"],
      "reason": "Message is typed against the SDK message protocol — the core contract of the whole set."
    },
    {
      "id": "message-streamdown",
